static int zms_write_ate(struct zms_fs *fs, zms_id_t id, uint16_t len, uint32_t data_offset)
{
	struct zms_ate ate;
	off_t ate_offset;
	int err;

	if (fs->ate_wra == ZMS_INVALID_ADDR) {
		return -EACCES;
	}

	ate_offset = fs->offset +
		     (fs->sector_size * SECTOR_NUM(fs->ate_wra)) +
		     SECTOR_OFFSET(fs->ate_wra);

	ate.id = id;
	ate.len = len;
	ate.offset = data_offset;
	ate.cycle_cnt = fs->sector_cycle;
	ate.metadata = FIELD_PREP(ZMS_VERSION_MASK, ZMS_DEFAULT_VERSION) |
		       FIELD_PREP(ZMS_MAGIC_NUMBER_MASK, ZMS_MAGIC_NUMBER) |
		       FIELD_PREP(ZMS_ATE_FORMAT_MASK, ZMS_DEFAULT_ATE_FORMAT);
	ate.crc8 = crc8_ccitt(0xff, (uint8_t *)&ate, fs->ate_size);

	err = flash_write(fs->flash_device, ate_offset, &ate, fs->ate_size);
	if (err) {
		return err;
	}

	fs->ate_wra += fs->ate_size;

	return 0;
}
